def get_comment_spec(lang):
    if lang in HTML_LANGS and lang not in {'Markdown'}:
        return [], [('<!--','-->')]
    if lang in CSS_LANGS:
        return [], [('/*','*/')]
    if lang in SQL_LANGS:
        return ['--'], [('/*','*/')]
    if lang in CSTYLE_LANGS:
        line=['//']
        if lang=='PHP': line=['//','#']
        return line, [('/*','*/')]
    if lang in DASH_LANGS:
        return ['--'], [('--[[',']]')] if lang=='Lua' else []
    if lang in HASH_LANGS:
        return ['#'], []
    if lang=='Ruby': return ['#'], [('=begin','=end')]
    return [], []


def strip_inline_for_complexity(line, lang):
    s=line
    if lang=='Python':
        # crude but matches common inline-comment cases
        idx=s.find('#')
        if idx>=0: s=s[:idx]
        s=re.sub(r"'''[^']*'''", " ", s); s=re.sub(r'"""[^"]*"""', ' ', s)
        return s
    markers, blocks=get_comment_spec(lang)
    for start,end in blocks:
        while start in s:
            i=s.find(start); j=s.find(end,i+len(start))
            if j<0: s=s[:i]; break
            s=s[:i]+' '+s[j+len(end):]
    best=len(s)+1
    for m in markers:
        i=s.find(m)
        if i>=0: best=min(best,i)
    if best<=len(s): s=s[:best]
    return s


def count_complexity(lang, code_line):
    s=strip_inline_for_complexity(code_line, lang)
    if not s.strip(): return 0
    def words(*ws):
        return sum(len(re.findall(r'\b'+re.escape(w)+r'\b', s)) for w in ws)
    if lang=='Python':
        return words('if','elif','else','for','while','except','try','with','and','or','case')
    if lang in {'Ruby'}:
        return words('if','elsif','else','for','while','rescue','case','when') + s.count('&&') + s.count('||')
    if lang in {'Shell','BASH','Zsh','Fish'}:
        return words('if','for','while','case','elif')
    if lang in {'Go','Rust','C','C++','C Header','C++ Header','Java','Kotlin','Scala','Swift','Dart'}:
        return words('if','for','while','switch','catch','try','match','select') + s.count('&&') + s.count('||')
    if lang in {'JavaScript','TypeScript','JSX','TSX','TypeScript Typings','Vue'}:
        return words('if','for','while') + s.count('&&') + s.count('||')
    if lang in {'C#'}:
        return words('if','for','foreach','while','switch','catch','try') + s.count('&&') + s.count('||')
    if lang=='PHP':
        return words('if','for','foreach','while','switch','catch','elseif','else')
    if lang in SQL_LANGS:
        return words('if','case','when','loop','while')
    return 0


def analyse_lines(text, lang, opts):
    # splitlines() mirrors the observed behavior for trailing newlines.
    lines=text.splitlines()
    blank=comment=code=complexity=0
    maxlen=0; sumlen=0
    in_block=None
    py_triple=None
    ruby_block=False
    line_markers, block_markers=get_comment_spec(lang)
    for line in lines:
        l=line[:-1] if line.endswith('\r') else line
        maxlen=max(maxlen,len(l)); sumlen+=len(l)
        stripped=l.strip()
        if stripped=='':
            blank+=1; continue
        classified=None
        # Python standalone triple-quoted strings are comments.
        if lang=='Python':
            if py_triple:
                end=py_triple; idx=l.find(end)
                if idx>=0:
                    after=l[idx+len(end):].strip(); py_triple=None
                    if after:
                        code+=1; classified='code'
                    else:
                        comment+=1; classified='comment'
                else:
                    comment+=1; classified='comment'
            else:
                lead=len(l)-len(l.lstrip())
                start3=None
                if l.startswith("'''", lead): start3="'''"
                elif l.startswith('"""', lead): start3='"""'
                if start3:
                    idx=l.find(start3, lead+3)
                    if idx>=0:
                        after=l[idx+3:].strip()
                        if after:
                            code+=1; classified='code'
                        else:
                            comment+=1; classified='comment'
                    else:
                        py_triple=start3; comment+=1; classified='comment'
        if classified is None and lang=='Ruby':
            if ruby_block:
                if stripped.startswith('=end'): ruby_block=False
                comment+=1; classified='comment'
            elif stripped.startswith('=begin'):
                ruby_block=True; comment+=1; classified='comment'
        if classified is None and in_block:
            end=in_block
            idx=l.find(end)
            if idx>=0:
                after=l[idx+len(end):].strip(); in_block=None
                if after:
                    code+=1; classified='code'
                else:
                    comment+=1; classified='comment'
            else:
                comment+=1; classified='comment'
        if classified is None:
            lead=len(l)-len(l.lstrip())
            # line comment at first non-whitespace
            lm=None
            for m in line_markers:
                if l.startswith(m, lead): lm=m; break
            if lm:
                comment+=1; classified='comment'
            else:
                # block comment at first non-whitespace
                bm=None
                for start,end in block_markers:
                    if l.startswith(start, lead): bm=(start,end); break
                if bm:
                    start,end=bm; eidx=l.find(end, lead+len(start))
                    if eidx>=0:
                        after=l[eidx+len(end):].strip()
                        if after:
                            code+=1; classified='code'
                        else:
                            comment+=1; classified='comment'
                    else:
                        in_block=end; comment+=1; classified='comment'
                else:
                    code+=1; classified='code'
                    # code line can start a following block comment
                    earliest=None
                    for start,end in block_markers:
                        idx=l.find(start)
                        if idx>=0 and l.find(end, idx+len(start))<0:
                            if earliest is None or idx<earliest[0]: earliest=(idx,end)
                    if earliest is not None: in_block=earliest[1]
        if classified=='code' and not opts.no_complexity:
            complexity += count_complexity(lang, l)
    mean = int(sumlen/len(lines)) if lines else 0
    return {'Lines':len(lines),'Blank':blank,'Comment':comment,'Code':code,'Complexity':0 if opts.no_complexity else complexity,'MaxLine':maxlen,'MeanLine':mean,'LineStrings':lines}

class FileStat:
    __slots__ = ('Language','PossibleLanguages','Filename','Extension','Location','Symlocation','Bytes','Lines','Code','Comment','Blank','Complexity','WeightedComplexity','Hash','Binary','Minified','Generated','EndPoint','Uloc','MaxLine','MeanLine','_uloc_set')
    def to_json(self):
        return {
            'Language':self.Language,'PossibleLanguages':self.PossibleLanguages,'Filename':self.Filename,'Extension':self.Extension,
            'Location':self.Location,'Symlocation':self.Symlocation,'Bytes':self.Bytes,'Lines':self.Lines,'Code':self.Code,
            'Comment':self.Comment,'Blank':self.Blank,'Complexity':self.Complexity,'WeightedComplexity':self.WeightedComplexity,
            'Hash':self.Hash,'Binary':self.Binary,'Minified':self.Minified,'Generated':self.Generated,'EndPoint':self.EndPoint,'Uloc':self.Uloc
        }


def path_matches_any(path, patterns):
    for rx in patterns:
        try:
            if re.search(rx, path): return True
        except re.error:
            pass
    return False


def read_ignore_file(fn):
    pats=[]
    try:
        for line in open(fn, encoding='utf-8', errors='ignore'):
            s=line.strip()
            if not s or s.startswith('#') or s.startswith('!'): continue
            pats.append(s)
    except Exception:
        pass
    return pats


def ignored_by_patterns(rel, name, is_dir, patterns):
    rel=rel.replace(os.sep,'/')
    for p in patterns:
        neg=False
        if p.startswith('!'):
            continue
        p=p.strip()
        if not p: continue
        dironly=p.endswith('/')
        pp=p.rstrip('/')
        if dironly and not is_dir: continue
        if '/' not in pp:
            if fnmatch.fnmatch(name, pp) or fnmatch.fnmatch(rel, pp): return True
        else:
            if fnmatch.fnmatch(rel, pp) or rel.startswith(pp.rstrip('/')+'/'): return True
    return False


def collect_files(paths, opts):
    if not paths: paths=['.']
    exclude_dirs=DEFAULT_EXCLUDE_DIRS[:]
    if opts.exclude_dir is not None:
        vals=split_list(opts.exclude_dir)
        if vals==['']: vals=[]
        exclude_dirs += [v for v in vals if v]
    exclude_files=DEFAULT_EXCLUDE_FILES[:]
    if opts.exclude_file is not None:
        vals=split_list(opts.exclude_file)
        if vals==['']: exclude_files=[]
        else: exclude_files=[v for v in vals if v]
    not_match=opts.not_match[:]
    entries=[]
    for arg in paths:
        if not os.path.exists(arg) and not os.path.islink(arg):
            print(f"file or directory could not be read: {arg}")
            sys.exit(1)
        if os.path.islink(arg):
            if not opts.include_symlinks: continue
            real=os.path.realpath(arg)
            entries.append((arg, real, True, True)); continue
        if os.path.isfile(arg):
            entries.append((arg, arg, True, False)); continue
        if os.path.isdir(arg):
            root_display=arg.rstrip('/') if arg != '/' else arg
            ignore_pats=[]
            # root ignore files are enough for most use; add subdir files as we walk.
            if not opts.no_gitignore: ignore_pats += read_ignore_file(os.path.join(arg,'.gitignore'))
            if not opts.no_ignore: ignore_pats += read_ignore_file(os.path.join(arg,'.ignore'))
            if not opts.no_scc_ignore: ignore_pats += read_ignore_file(os.path.join(arg,'.sccignore'))
            for cur, dirs, files in os.walk(arg, followlinks=opts.include_symlinks):
                rel_dir=os.path.relpath(cur,arg)
                if rel_dir=='.': rel_dir=''
                # add ignore files in subdirectories
                if cur != arg:
                    if not opts.no_gitignore: ignore_pats += read_ignore_file(os.path.join(cur,'.gitignore'))
                    if not opts.no_ignore: ignore_pats += read_ignore_file(os.path.join(cur,'.ignore'))
                    if not opts.no_scc_ignore: ignore_pats += read_ignore_file(os.path.join(cur,'.sccignore'))
                newdirs=[]
                for d in sorted(dirs):
                    rel=os.path.join(rel_dir,d) if rel_dir else d
                    if d in exclude_dirs or path_matches_any(rel, not_match) or ignored_by_patterns(rel,d,True,ignore_pats):
                        continue
                    newdirs.append(d)
                dirs[:] = newdirs
                for f in sorted(files):
                    real=os.path.join(cur,f)
                    islink=os.path.islink(real)
                    if islink and not opts.include_symlinks: continue
                    rel=os.path.join(rel_dir,f) if rel_dir else f
                    if f in exclude_files: continue
                    if path_matches_any(rel, not_match): continue
                    if ignored_by_patterns(rel,f,False,ignore_pats): continue
                    if f in ('.gitignore','.ignore') and not opts.count_ignore: continue
                    if f=='.sccignore': continue
                    display=os.path.join(root_display,rel) if root_display not in ('.','') else rel
                    entries.append((display, os.path.realpath(real) if islink else real, False, islink))
    return entries


def process(entries, opts):
    count_as=parse_count_as(opts.count_as)
    include_exts=set(e for e in split_list(opts.include_ext) if e) if opts.include_ext is not None else None
    exclude_exts=set(e for e in split_list(opts.exclude_ext) if e) if opts.exclude_ext is not None else set()
    markers=[m.lower() for m in (split_list(opts.generated_markers) if opts.generated_markers is not None else DEFAULT_MARKERS)]
    files=[]; seen=set()
    for display, real, direct, islink in entries:
        try:
            data=open(real,'rb').read()
        except Exception as e:
            warn(opts, f"error reading: {display} error opening {display}: {e}")
            continue
        lang, possible, ext, shebang = detect_language(display, data, opts, count_as)
        if not lang: continue
        ext_key=(ext or '').lower().lstrip('.')
        if include_exts is not None and ext_key not in include_exts:
            continue
        if ext_key in exclude_exts:
            continue
        h=None
        if opts.no_duplicates:
            digest=hashlib.sha1(data).digest()
            if digest in seen: continue
            seen.add(digest); h={}
        text=data.decode('utf-8','replace')
        stats=analyse_lines(text, lang.replace(' (gen)','').replace(' (min)',''), opts)
        if opts.no_large and (len(data) > opts.large_byte_count or stats['Lines'] > opts.large_line_count):
            continue
        lines=stats['LineStrings']
        avg_line=(len(data)/stats['Lines']) if stats['Lines'] else 0
        minified=False; generated=False
        if opts.min or opts.min_gen:
            minified = avg_line > opts.min_gen_line_length
        if opts.gen or opts.min_gen:
            head='\n'.join(lines[:20]).lower()
            generated=any(m and m in head for m in markers)
        if opts.no_min and minified: continue
        if opts.no_gen and generated: continue
        if opts.no_min_gen and (minified or generated): continue
        out_lang=lang
        if generated: out_lang=f"{lang} (gen)"
        elif minified: out_lang=f"{lang} (min)"
        fs=FileStat(); fs.Language=out_lang; fs.PossibleLanguages=possible or [lang]
        fs.Filename=display if direct else os.path.basename(display)
        fs.Extension=ext; fs.Location=display; fs.Symlocation=os.readlink(display) if islink and os.path.islink(display) else ''
        fs.Bytes=len(data); fs.Lines=stats['Lines']; fs.Code=stats['Code']; fs.Comment=stats['Comment']; fs.Blank=stats['Blank']; fs.Complexity=stats['Complexity']
        fs.WeightedComplexity=0; fs.Hash=h; fs.Binary=False; fs.Minified=minified; fs.Generated=generated; fs.EndPoint=0
        ulines=lines[:]
        while ulines and ulines[-1].strip()=='': ulines.pop()
        fs._uloc_set=set(ulines); fs.Uloc=len(fs._uloc_set) if opts.uloc else 0
        fs.MaxLine=stats['MaxLine']; fs.MeanLine=stats['MeanLine']
        files.append(fs)
    return files


def summarize(files, opts, include_files=False):
    groups={}
    for f in files:
        g=groups.setdefault(f.Language, {'Name':f.Language,'Bytes':0,'CodeBytes':0,'Lines':0,'Code':0,'Comment':0,'Blank':0,'Complexity':0,'Count':0,'WeightedComplexity':0,'Files':[],'LineLength':None,'ULOC':0,'MaxLine':0,'SumLineLen':0,'LineCountForMean':0,'_uloc_set':set()})
        g['Bytes']+=f.Bytes; g['Lines']+=f.Lines; g['Code']+=f.Code; g['Comment']+=f.Comment; g['Blank']+=f.Blank; g['Complexity']+=f.Complexity; g['Count']+=1
        g['MaxLine']=max(g['MaxLine'], f.MaxLine); g['LineCountForMean']+=f.Lines; g['SumLineLen']+=f.MeanLine*f.Lines
        g['_uloc_set'].update(f._uloc_set)
        if include_files: g['Files'].append(f)
    arr=list(groups.values())
    for g in arr:
        if opts.uloc: g['ULOC']=len(g['_uloc_set'])
        g['MeanLine']=int(g['SumLineLen']/g['LineCountForMean']) if g['LineCountForMean'] else 0
        if include_files: g['Files'].sort(key=lambda f:f.Location)
    sort_key=opts.sort if opts.sort in {'files','name','lines','blanks','code','comments','complexity'} else 'files'
    if sort_key=='name': arr.sort(key=lambda g:g['Name'].lower())
    else:
        field={'files':'Count','lines':'Lines','blanks':'Blank','code':'Code','comments':'Comment','complexity':'Complexity'}[sort_key]
        if sort_key=='files': arr.sort(key=lambda g:(-g[field],-g['Lines'],g['Name'].lower()))
        else: arr.sort(key=lambda g:(-g[field],g['Name'].lower()))
    return arr


def total_from_summaries(summaries):
    t={'Name':'Total','Bytes':0,'Lines':0,'Code':0,'Comment':0,'Blank':0,'Complexity':0,'Count':0,'ULOC':0}
    for g in summaries:
        for k in ['Bytes','Lines','Code','Comment','Blank','Complexity','Count']: t[k]+=g[k]
    return t


def cocomo(code, opts):
    if code<=0: return 0,0,0
    typ=opts.cocomo_project_type
    if typ.startswith('custom,'):
        try:
            _,a,b,c,d=typ.split(',',4); a=float(a); b=float(b); c=float(c); d=float(d)
        except Exception:
            a,b,c,d=2.4,1.05,2.5,0.38; typ='organic'
    elif typ=='semi-detached': a,b,c,d=3.0,1.12,2.5,0.35
    elif typ=='embedded': a,b,c,d=3.6,1.20,2.5,0.32
    else: a,b,c,d=2.4,1.05,2.5,0.38
    kloc=code/1000.0
    effort=a*(kloc**b)*opts.eaf
    schedule=c*(effort**d) if effort>0 else 0
    people=effort/schedule if schedule else 0
    monthly=int(opts.avg_wage/12)
    cost=effort*monthly*opts.overhead
    return cost,schedule,people


def locomo_est(total, opts):
    code=max(0,total['Code']); comp=max(0,total['Complexity'])
    presets={'large':(5.0,15.0,30.0),'medium':(3.0,15.0,50.0),'small':(0.5,1.5,80.0),'local':(0.0,0.0,20.0)}
    ip,op,tps=presets.get(opts.locomo_preset, presets['medium'])
    if opts.locomo_input_price is not None: ip=opts.locomo_input_price
    if opts.locomo_output_price is not None: op=opts.locomo_output_price
    if opts.locomo_tps is not None: tps=opts.locomo_tps
    ratio=(comp/code) if code else 0
    avg_mult=1+27.95448267190433*ratio
    cycles=opts.locomo_cycles if opts.locomo_cycles is not None else 1+4.964101615137754*ratio
    input_tokens=code*20*avg_mult
    output_tokens=code*10*cycles
    cost=input_tokens/1_000_000*ip + output_tokens/1_000_000*op
    seconds=output_tokens/tps if tps else 0
    review_hours=code*opts.locomo_review/60.0
    return cost,input_tokens,output_tokens,seconds,review_hours,avg_mult,cycles


def comma(n): return f"{int(n):,}"

def money_int(x, sym='$'):
    return sym + f"{int(x):,}"

def trunc_name(s, wide=False):
    limit=22 if wide else 15
    if len(s)>limit: return s[:limit-1]+'…'
    return s

NORMAL_FMT = "%-18s %6s %11s %9s %9s %10s %10s"
NOCOMP_FMT = "%-26s %6s %11s %10s %11s %10s"
WIDE_FMT = "%-36s %6s %9s %8s %9s %8s %10s %16s"

def row_normal(name, files, lines, blanks, comments, code, complexity, no_complex=False):
    if no_complex:
        return NOCOMP_FMT % (trunc_name(name,False), files, lines, blanks, comments, code)
    return NORMAL_FMT % (trunc_name(name,False), files, lines, blanks, comments, code, complexity)

def row_file(name, lines, blanks, comments, code, complexity, no_complex=False):
    if no_complex:
        return NOCOMP_FMT % (trunc_name(name,False), '', lines, blanks, comments, code)
    return NORMAL_FMT % (trunc_name(name,False), '', lines, blanks, comments, code, complexity)

def row_wide(name, files, lines, blanks, comments, code, complexity, ratio):
    return WIDE_FMT % (trunc_name(name,True), files, lines, blanks, comments, code, complexity, ratio)

def ratio_str(comp, code):
    return f"{(comp/code*100) if code else 0:.2f}"

def border(opts, wide=False):
    if opts.no_hborder: return None
    return ('-' if opts.ci else '─') * (109 if wide else 79)

def fmt_size(bytes_, opts):
    unit=opts.size_unit.lower()
    label={'si':'SI','binary':'BINARY','mixed':'MIXED','xkcd-kb':'XKCD-KB','xkcd-kelly':'XKCD-KELLY','xkcd-imaginary':'XKCD-IMAGINARY','xkcd-intel':'XKCD-INTEL','xkcd-drive':'XKCD-DRIVE','xkcd-bakers':'XKCD-BAKERS'}.get(unit,'SI')
    if unit=='xkcd-imaginary': mb='¯\\_(ツ)_/¯'
    else:
        denom=1024*1024 if unit=='binary' else 1000*1000
        mb=f"{bytes_/denom:.3f}"
    return f"Processed {bytes_} bytes, {mb} megabytes ({label})"


def render_table(summaries, files, opts, wide=False):
    out=[]; b=border(opts, wide); total=total_from_summaries(summaries)
