        rr=(g['Complexity']/g['Code']*100) if g['Code'] else 0.0; total_ratio_sum+=rr
        if wide: out.append(row_wide(g['Name'], *vals, f"{rr:.2f}"))
        else: out.append(row_normal(g['Name'], *vals, no_complex=opts.no_complexity))
