def summary_json_obj(g, include_files):
    return {'Name':g['Name'],'Bytes':g['Bytes'],'CodeBytes':0,'Lines':g['Lines'],'Code':g['Code'],'Comment':g['Comment'],'Blank':g['Blank'],'Complexity':g['Complexity'],'Count':g['Count'],'WeightedComplexity':0,'Files':[f.to_json() for f in g.get('Files',[])] if include_files else [],'LineLength':None,'ULOC':g.get('ULOC',0)}


