def render_cloc_yaml(summaries, files):
    total=total_from_summaries(summaries); elapsed=0.001
    fps=int(total['Count']/elapsed) if elapsed else 0; lps=int(total['Lines']/elapsed) if elapsed else 0
    out=['# https://github.com/boyter/scc/','header:','  url: https://github.com/boyter/scc/','  version: 3.7.0',f'  elapsed_seconds: {elapsed:.3f}',f'  n_files: {total["Count"]}',f'  n_lines: {total["Lines"]}',f'  files_per_second: {fps}',f'  lines_per_second: {lps}']
