    out += ['SUM:',f'  code: {total["Code"]}',f'  comment: {total["Comment"]}',f'  blank: {total["Blank"]}',f'  nFiles: {total["Count"]}']
    return '\n'.join(out)+'\n'


def sql_quote(s): return str(s).replace("'","''")

def render_sql(files, summaries, opts, inserts_only=False):
    total=total_from_summaries(summaries); cost,sched,people=cocomo(total['Code'],opts)
    project=opts.sql_project or (files[0].Location if len(files)==1 else (os.path.commonpath([f.Location for f in files]) if files else ''))
    if project=='.': project='.'
    ts=datetime.datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')
    out=[]
    if not inserts_only:
        out.append('create table metadata (   -- github.com/boyter/scc v 3.7.0')
        out.append('             timestamp text,')
        out.append('             Project   text,')
        out.append('             elapsed_s real,')
        out.append('             estimated_cost real,')
        out.append('             estimated_schedule_months real,')
        out.append('             estimated_people real);')
        out.append('create table t        (')
        out.append('             Project       text   ,')
        out.append('             Language      text   ,')
        out.append('             File          text   ,')
        out.append('             File_dirname  text   ,')
        out.append('             File_basename text   ,')
        out.append('             nByte         integer,')
        out.append('             nBlank        integer,')
        out.append('             nComment      integer,')
        out.append('             nCode         integer,')
        out.append('             nComplexity   integer,')
        out.append('             nUloc         integer    ')
        out.append(');')
    else:
        out.append('')
    out.append('begin transaction;')
    for f in files:
        d=os.path.dirname(f.Location); b=os.path.basename(f.Location)
        out.append(f"insert into t values('{sql_quote(project)}', '{sql_quote(f.Language)}', '{sql_quote(f.Location)}', '{sql_quote(d)}', '{sql_quote(b)}', {f.Bytes}, {f.Blank}, {f.Comment}, {f.Code}, {f.Complexity}, {f.Uloc if opts.uloc else 0});")
    out.append('commit;')
    out.append('begin transaction;')
    out.append(f"insert into metadata values('{ts}', '{sql_quote(project)}', 0.001000, {cost:.6f}, {sched:.6f}, {people:.6f});")
    out.append('commit;')
    return '\n'.join(out)


def render_openmetrics(summaries):
    out=['# TYPE scc_files gauge','# HELP scc_files Number of sourcecode files.','# TYPE scc_lines gauge','# HELP scc_lines Number of lines.','# TYPE scc_code gauge','# HELP scc_code Number of lines of actual code.','# TYPE scc_comments gauge','# HELP scc_comments Number of comments.','# TYPE scc_blanks gauge','# HELP scc_blanks Number of blank lines.','# TYPE scc_complexity gauge','# HELP scc_complexity Code complexity.','# TYPE scc_bytes gauge','# UNIT scc_bytes bytes','# HELP scc_bytes Size in bytes.']
    for g in summaries:
        lang=g['Name'].replace('"','\\"')
        out += [f'scc_files{{language="{lang}"}} {g["Count"]}',f'scc_lines{{language="{lang}"}} {g["Lines"]}',f'scc_code{{language="{lang}"}} {g["Code"]}',f'scc_comments{{language="{lang}"}} {g["Comment"]}',f'scc_blanks{{language="{lang}"}} {g["Blank"]}',f'scc_complexity{{language="{lang}"}} {g["Complexity"]}',f'scc_bytes{{language="{lang}"}} {g["Bytes"]}']
    return '\n'.join(out)+'\n'


def render_html(summaries, opts, table_only=False):
    total=total_from_summaries(summaries); cost,sched,people=cocomo(total['Code'],opts)
    out=['<table id="scc-table">','\t<thead><tr>']
    for h in ['Language','Files','Lines','Blank','Comment','Code','Complexity','Bytes','Uloc']:
        out.append(f'\t\t<th>{h}</th>')
    out.append('\t</tr></thead>'); out.append('\t<tbody>')
    for g in summaries:
        out.append('\t<tr>')
        for v in [g['Name'],g['Count'],g['Lines'],g['Blank'],g['Comment'],g['Code'],g['Complexity'],g['Bytes'],g.get('ULOC',0)]: out.append(f'\t\t<th>{htmlmod.escape(str(v))}</th>')
        out.append('\t</tr>')
    out.append('\t</tbody>'); out.append('\t<tfoot><tr>')
    for v in ['Total',total['Count'],total['Lines'],total['Blank'],total['Comment'],total['Code'],total['Complexity'],total['Bytes'],0]: out.append(f'\t\t<th>{v}</th>')
    out.append('\t</tr>')
    if not opts.no_cocomo:
        typ=opts.cocomo_project_type if not opts.cocomo_project_type.startswith('custom') else 'custom'
        out.append('\t<tr>')
        out.append(f'\t\t<th colspan="9">Estimated Cost to Develop ({typ}) {money_int(cost,opts.currency_symbol)}<br>Estimated Schedule Effort ({typ}) {sched:.2f} months<br>Estimated People Required ({typ}) {people:.2f}<br></th>')
        out.append('\t</tr>')
    out.append('\t</tfoot>'); out.append('\t</table>')
    table='\n'.join(out)
    if table_only: return table
    return '<html lang="en"><head><meta charset="utf-8" /><title>scc html output</title><style>table { border-collapse: collapse; }td, th { border: 1px solid #999; padding: 0.5rem; text-align: left;}</style></head><body>'+table+'</body></html>\n'


def render(fmt, summaries, files, opts):
    if opts.wide or fmt=='wide': return render_table(summaries, files, opts, wide=True)
    if fmt=='json': return render_json(summaries, opts.by_file)
    if fmt=='json2': return render_json2(summaries, opts, files)
    if fmt=='csv': return render_csv(summaries, files, opts, False)
    if fmt=='csv-stream': return render_csv(summaries, files, opts, True)
    if fmt=='cloc-yaml': return render_cloc_yaml(summaries, files)
    if fmt=='sql': return render_sql(files, summaries, opts, False)
    if fmt=='sql-insert': return render_sql(files, summaries, opts, True)
    if fmt=='openmetrics': return render_openmetrics(summaries)
    if fmt=='html': return render_html(summaries, opts, False)
    if fmt=='html-table': return render_html(summaries, opts, True)
    return render_table(summaries, files, opts, wide=False)


def main(argv):
    opts, paths, err=parse_args(argv)
    if err:
        sys.stderr.write(f"Error: {err}\n"+USAGE_TEXT)
        return 1
    if opts.help:
        sys.stdout.write(HELP_TEXT); return 0
    if opts.version:
        print(f"scc version {VERSION}"); return 0
    if opts.languages:
        sys.stdout.write(LANGS_RAW if LANGS_RAW.endswith('\n') else LANGS_RAW+'\n'); return 0
    if opts.mcp:
        # A tiny, harmless stand-in for stdio MCP mode.
        return 0
    entries=collect_files(paths, opts)
    files=process(entries, opts)
    # csv-stream uses discovery order; other file outputs use sorted discovery for deterministic presentation.
    summaries=summarize(files, opts, include_files=opts.by_file or opts.format in {'json','json2'})
    fmt=opts.format if opts.format in VALID_FORMATS else 'tabular'
    if opts.wide: fmt='wide'
    if opts.format_multi:
        for spec in split_list(opts.format_multi):
            if ':' in spec: f,target=spec.split(':',1)
            else: f,target=spec,'stdout'
            f=f if f in VALID_FORMATS else 'tabular'
            content=render(f, summaries, files, opts)
            if target=='stdout' or target=='-': sys.stdout.write(content)
            else:
                with open(target,'w',encoding='utf-8') as fh: fh.write(content)
        return 0
    content=render(fmt, summaries, files, opts)
    if opts.output and opts.output != 'stdout':
        with open(opts.output,'w',encoding='utf-8') as fh: fh.write(content)
        print(f"results written to {opts.output}")
    else:
        sys.stdout.write(content)
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
