def split_list(v):
    if v is None:
        return []
    if isinstance(v, list):
        vals=[]
        for x in v: vals.extend(split_list(x))
        return vals
    # Use csv reader so quoted language names survive: a:b,c:"C Header"
    try:
        return [x for x in next(csv.reader([str(v)], skipinitialspace=True))]
    except Exception:
        return [p.strip() for p in str(v).split(',')]

