def coerce(opts):
    for name in ['avg_wage','directory_walker_job_workers','file_gc_count','file_list_queue_size','file_process_job_workers','file_summary_job_queue_size','large_byte_count','large_line_count','min_gen_line_length']:
        try: setattr(opts,name,int(getattr(opts,name)))
        except Exception: setattr(opts,name,0)
    for name in ['eaf','overhead','locomo_review']:
        try: setattr(opts,name,float(getattr(opts,name)))
        except Exception: pass
    for name in ['locomo_cycles','locomo_input_price','locomo_output_price','locomo_tps']:
        v=getattr(opts,name)
        if v is not None:
            try: setattr(opts,name,float(v))
            except Exception: setattr(opts,name,None)
    if opts.dryness: opts.uloc=True
    if opts.cost_comparison: opts.locomo=True
    if opts.no_gen: opts.gen=True
    if opts.no_min: opts.min=True
    if opts.no_min_gen: opts.min_gen=True
    if opts.min_gen:
        opts.min=True; opts.gen=True
    return opts


def parse_args(argv):
    opts=Options(); paths=[]; i=0
    while i < len(argv):
        a=argv[i]
        if a == '--':
            paths.extend(argv[i+1:]); break
        if a.startswith('--') and len(a)>2:
            flag=a; val=None
            if '=' in a:
                flag,val=a.split('=',1)
            if flag in BOOL_FLAGS:
                setattr(opts, BOOL_FLAGS[flag], True); i+=1; continue
            if flag in VALUE_FLAGS:
                if val is None:
                    i+=1
                    if i>=len(argv): val=''
                    else: val=argv[i]
                key=VALUE_FLAGS[flag]
                if key == 'not_match': opts.not_match.append(val)
                else: setattr(opts,key,val)
                i+=1; continue
            return None, [], f"unknown flag: {flag}"
        if a.startswith('-') and a != '-':
            if a in SHORT_BOOL:
                setattr(opts, BOOL_FLAGS[SHORT_BOOL[a]], True); i+=1; continue
            if a in SHORT_VALUE:
                key=VALUE_FLAGS[SHORT_VALUE[a]]; i+=1
                val=argv[i] if i<len(argv) else ''
                if key == 'not_match': opts.not_match.append(val)
                else: setattr(opts,key,val)
                i+=1; continue
            # support compact boolean clusters like -ucd
            ok=True
            for ch in a[1:]:
                sf='-'+ch
                if sf in SHORT_BOOL: setattr(opts, BOOL_FLAGS[SHORT_BOOL[sf]], True)
                else: ok=False; break
            if ok: i+=1; continue
            return None, [], f"unknown shorthand flag: '{a[1:2]}' in {a}"
        paths.append(a); i+=1
    return coerce(opts), paths, None


