def lang_from_target(target):
    t=target.strip().strip('"').strip("'")
    if t in LANG_EXTS: return t
    low=t.lower().lstrip('.')
    if low in EXT_LANGS:
        return choose_lang(low, EXT_LANGS[low])
    # case-insensitive language name
    for name in LANG_EXTS:
        if name.lower()==t.lower(): return name
    return None


def parse_count_as(s):
    remap={}
    for item in split_list(s):
        if not item or ':' not in item: continue
        a,b=item.split(':',1)
        ext=a.strip().lower().lstrip('.')
        lang=lang_from_target(b.strip())
        if lang: remap[ext]=lang
    return remap


def choose_lang(ext, possible):
    if not possible: return None
    if ext in PREFERRED and PREFERRED[ext] in possible: return PREFERRED[ext]
    # Prefer non-CloudFormation for normal json/yaml, and common language names.
    for p in possible:
        if p in ('JSON','YAML','Python','JavaScript','TypeScript','C Header','C++ Header'): return p
    return possible[-1] if ext in {'m','v'} else possible[0]


def detect_language(path, data, opts, count_as):
    base=os.path.basename(path); lower=base.lower(); possible=[]; ext=''
    # suffixes with multiple dots first, especially d.ts
    for suff, langs in sorted(EXT_LANGS.items(), key=lambda kv: -len(kv[0])):
        if '.' in suff and not suff.startswith('.') and lower.endswith('.'+suff):
            # exact build/cmake-like names report empty extension; suffix types report suffix
            if lower == suff and suff in SPECIAL_EXACT:
                possible=langs[:]; ext=''
            elif suff in ('cmakelists.txt','meson.build','meson_options.txt','bitbucket-pipelines.yml','build.bazel','xmake.lua','xpack.lua') and lower==suff:
                possible=langs[:]; ext=''
            elif suff in ('d.ts',):
                possible=langs[:]; ext=suff
            elif lower == suff:
                possible=langs[:]; ext=''
            else:
                possible=langs[:]; ext=suff
            break
    if not possible:
        if lower in SPECIAL_EXACT:
            possible=[SPECIAL_EXACT[lower]]; ext=base if '.' not in base else ''
        elif lower in HIDDEN_EXACT:
            possible=[HIDDEN_EXACT[lower]]; ext=base
        else:
            if '.' in base and not base.startswith('.'):
                ext=base.rsplit('.',1)[1].lower()
                if ext in count_as:
                    return count_as[ext], [count_as[ext]], ext, False
                possible=EXT_LANGS.get(ext, [])[:]
            elif base.startswith('.'):
                ext=base
                key=lower
                if key in count_as:
                    return count_as[key], [count_as[key]], ext, False
                possible=EXT_LANGS.get(key, [])[:]
            else:
                ext=base
    if ext.lower().lstrip('.') in count_as:
        lang=count_as[ext.lower().lstrip('.')]
        return lang, [lang], ext, False
    if possible:
        key=(ext or lower).lower()
        lang=choose_lang(key, possible)
        return lang, possible, ext, False
    # shebang for extensionless files
    if '.' not in base:
        warn(opts, f"possible #! file: {path}")
        first=data.splitlines()[:1]
        if first and first[0].startswith(b'#!'):
            line=first[0].decode('utf-8','ignore').lower()
            pairs=[('python','Python'),('bash','BASH'),('zsh','Zsh'),('node','JavaScript'),('ruby','Ruby'),('perl','Perl'),('php','PHP'),('awk','AWK'),('lua','Lua'),('sh','Shell')]
            for needle,lang in pairs:
                if needle in line:
                    warn(opts, f"detected #! {lang} for {path}")
                    return lang, ['#!'], base, True
        warn(opts, f"unable to determine #! language for {path}")
    else:
        warn(opts, f"skipping file unknown extension: {path}")
    return None, [], ext, False

