def sql_quote(s): return str(s).replace("'","''")

def render_sql(files, summaries, opts, inserts_only=False):
    total=total_from_summaries(summaries); cost,sched,people=cocomo(total['Code'],opts)
    project=opts.sql_project or (files[0].Location if len(files)==1 else (os.path.commonpath([f.Location for f in files]) if files else ''))
    if project=='.': project='.'
    ts=datetime.datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')
    out=[]
    if not inserts_only:
        out.append('create table metadata (   -- github.com/boyter/scc v 3.7.0')
        out.append('             timestamp text,')
        out.append('             Project   text,')
        out.append('             elapsed_s real,')
        out.append('             estimated_cost real,')
        out.append('             estimated_schedule_months real,')
        out.append('             estimated_people real);')
        out.append('create table t        (')
        out.append('             Project       text   ,')
        out.append('             Language      text   ,')
        out.append('             File          text   ,')
        out.append('             File_dirname  text   ,')
        out.append('             File_basename text   ,')
        out.append('             nByte         integer,')
        out.append('             nBlank        integer,')
        out.append('             nComment      integer,')
        out.append('             nCode         integer,')
        out.append('             nComplexity   integer,')
        out.append('             nUloc         integer    ')
        out.append(');')
    else:
        out.append('')
    out.append('begin transaction;')
    for f in files:
        d=os.path.dirname(f.Location); b=os.path.basename(f.Location)
        out.append(f"insert into t values('{sql_quote(project)}', '{sql_quote(f.Language)}', '{sql_quote(f.Location)}', '{sql_quote(d)}', '{sql_quote(b)}', {f.Bytes}, {f.Blank}, {f.Comment}, {f.Code}, {f.Complexity}, {f.Uloc if opts.uloc else 0});")
    out.append('commit;')
    out.append('begin transaction;')
    out.append(f"insert into metadata values('{ts}', '{sql_quote(project)}', 0.001000, {cost:.6f}, {sched:.6f}, {people:.6f});")
    out.append('commit;')
    return '\n'.join(out)


